import { AnyScaleBand } from '@visx/shape/lib/types';
import { isEmpty } from 'lodash-es';

import { ELLIPSIS_BUFFER } from './get-tick-label-props.js';
import {
  BOTTOM_AXIS_LINE_OFFSET,
  Y_AXES_LINE_OFFSET,
} from '../../../constants.js';
import {
  MIN_AXIS_TRUNCATION_SIZE,
  X_LABEL_AREA,
  Y_LABEL_AREA,
} from '../constants.js';

export const getLeftTickSize = (containerWidth: number, label?: string) => {
  const labelArea = isEmpty(label) ? 0 : Y_LABEL_AREA;

  const maxSize =
    Math.max(
      MIN_AXIS_TRUNCATION_SIZE,
      containerWidth - (Y_AXES_LINE_OFFSET + labelArea),
    ) + ELLIPSIS_BUFFER;

  return { maxSize, width: containerWidth };
};

export const getBottomTickSize = (
  containerHeight: number,
  isTickRotated: boolean,
  scale?: AnyScaleBand,
  label?: string,
) => {
  const labelArea = isEmpty(label) ? 0 : X_LABEL_AREA;

  const maxSize = isTickRotated
    ? containerHeight - (BOTTOM_AXIS_LINE_OFFSET + labelArea) + ELLIPSIS_BUFFER
    : scale
    ? scale.bandwidth() + (scale.step() - scale.bandwidth())
    : 0;

  const height = containerHeight;

  return { maxSize, height };
};
